bootforge/react-fundamentals/lists-and-s.solution:
const MEDALS = ['gold', 'silver', 'bronze'];

export function Leaderboard({ players }) {
  if (players.length === 0) {
    return { type: 'p', props: { className: 'empty' }, children: ['No players yet'] };
  }
  const top = [...players]
    .sort((a, b) => b.score - a.score || (a.name < b.name ? -1 : 1))
    .slice(0, 3);
  return {
    type: 'ol',
    props: { className: 'board' },
    children: top.map((p, i) => ({
