export function deriveView(state) {
  // compute every field from state.todos and state.filter
}

bootforge/react-fundamentals/lists-and-s.solution:
export function deriveView(state) {
  const { todos, filter } = state;
  let visible;
  if (filter === 'active') visible = todos.filter((t) => !t.done);
  else if (filter === 'completed') visible = todos.filter((t) => t.done);
  else visible = [...todos];
  const remaining = todos.filter((t) => !t.done).length;
  const allDone = todos.every((t) => t.done);
  let emptyMessage = null;
  if (visible.length === 0) {
    emptyMessage = filter === 'all' ? 'Add your first todo' : 'Nothing here';
  }
  return { visible, remaining, allDone, summary: remaining + ' left', emptyMessage };
}

