bootforge/react-fundamentals/lists-and-s.solution:
export function todosReducer(todos, action) {
  switch (action.type) {
    case 'add': {
      const id = todos.length === 0 ? 1 : Math.max(...todos.map((t) => t.id)) + 1;
      return [...todos, { id, text: action.text, done: false }];
    }
    case 'toggle':
      return todos.map((t) => (t.id === action.id ? { ...t, done: !t.done } : t));
    case 'remove':
      return todos.filter((t) => t.id !== action.id);
    case 'clearCompleted':
      return todos.filter((t) => !t.done);
    default:
      return [...todos];
  }
}

