export function signupState(form, touched, submitting) {
  // 1. build errors from the rules
  // 2. gate them through touched for visibleErrors
  // 3. compute canSubmit
}

bootforge/react-fundamentals/lists-and-s.solution:
export function signupState(form, touched, submitting) {
  const errors = {};
  if (form.email.trim() === '') errors.email = 'Required';
  else if (!form.email.includes('@')) errors.email = 'Invalid email';
  if (form.password === '') errors.password = 'Required';
  else if (!(form.password.length >= 8 && /[0-9]/.test(form.password) && /[A-Z]/.test(form.password))) {
    errors.password = 'Password too weak';
  }
  if (form.confirm !== form.password) errors.confirm = 'Passwords do not match';
  const visibleErrors = {};
  for (const key of Object.keys(errors)) {
    if (touched[key]) visibleErrors[key] = errors[key];
  }
  const canSubmit = Object.keys(errors).length === 0 && !submitting;
  return { errors, visibleErrors, canSubmit };
}
